"""The Azure Activity Log SourceAdapter (ADR-0011 batch C).

One Observation per Activity Log event in the **Azure Monitor REST API** form
(``eventDataId``, ``eventTimestamp``, ``operationName`` / ``category`` /
``resourceProviderName`` / ``status`` as ``{value, localizedValue}`` objects,
``caller``, ``subscriptionId``, ``httpRequest``, ``properties``). The
diagnostic-setting export of the same events (flat upper-case
``operationName``) is a different layout and is not read here: no sample of it
exists to validate against.

**Event time:** ``eventTimestamp`` (when the event was generated by the service
processing the request), ISO 8601 with a zone; without one it is refused.

**Exact values:** the ``azure_activity`` group holds the ``.value`` of each
localizable object — the Log Analytics ``AzureActivity`` columns Sigma's
``azure/activitylogs`` rules read (``OperationNameValue``, ``CategoryValue``,
``ResourceProviderValue``) — and ``resourceId`` / ``properties.message`` as
logged; a field the record does not carry stays absent (``category`` is absent
in older records, which carry ``eventSource`` instead; it is not substituted).
ECS: ``cloud.provider`` = ``azure``, ``cloud.account.id`` = ``subscriptionId``;
``user.name`` = ``caller``; ``network.source.ip`` = ``httpRequest.clientIpAddress``
when it is an IP address; ``event.action`` = ``operationName.value``.
"""

from __future__ import annotations

import hashlib
import json
from collections.abc import Mapping
from typing import Any

from attribution_platform.domain import (
    AzureActivityRef,
    CloudRef,
    EventMetadata,
    NetworkEndpoint,
    NetworkInfo,
    Observation,
    SourceRef,
    UserRef,
)
from attribution_platform.sources.errors import SourceAdapterError
from attribution_platform.sources.json_values import at_path, ip_or_none, zoned_iso_time

AZURE_ACTIVITY_SOURCE_TYPE = "azure_activity"
AZURE_ACTIVITY_DATASET = "azure.activitylogs"
_ADAPTER = "AzureActivitySourceAdapter"


def is_azure_activity_record(record: Mapping[str, Any]) -> bool:
    """Whether ``record`` is one Activity Log event in the REST API form."""
    return (
        "eventDataId" in record
        and "eventTimestamp" in record
        and isinstance(record.get("operationName"), Mapping)
    )


def _at(record: Mapping[str, Any], *path: str) -> str | None:
    return at_path(record, path, _ADAPTER)


class AzureActivitySourceAdapter:
    """Azure Activity Log events (REST form) -> one ``Observation`` each."""

    @property
    def source_type(self) -> str:
        return AZURE_ACTIVITY_SOURCE_TYPE

    def to_observations(self, raw_record: Any) -> tuple[Observation, ...]:
        if not isinstance(raw_record, Mapping) or not is_azure_activity_record(raw_record):
            raise SourceAdapterError(f"{_ADAPTER}: not an Activity Log event (REST form)")
        timestamp, precision = zoned_iso_time(
            raw_record["eventTimestamp"], "eventTimestamp", _ADAPTER
        )
        event_data_id = _at(raw_record, "eventDataId")
        subscription = _at(raw_record, "subscriptionId")
        if event_data_id is None or subscription is None:
            raise SourceAdapterError(f"{_ADAPTER}: eventDataId and subscriptionId are required")
        operation = _at(raw_record, "operationName", "value")
        activity = AzureActivityRef(
            event_data_id=event_data_id,
            operation_id=_at(raw_record, "operationId"),
            correlation_id=_at(raw_record, "correlationId"),
            operation_name=operation,
            category=_at(raw_record, "category", "value"),
            resource_provider=_at(raw_record, "resourceProviderName", "value"),
            resource_id=_at(raw_record, "resourceId"),
            resource_group=_at(raw_record, "resourceGroupName"),
            status=_at(raw_record, "status", "value"),
            sub_status=_at(raw_record, "subStatus", "value"),
            level=_at(raw_record, "level"),
            caller=_at(raw_record, "caller"),
            authorization_action=_at(raw_record, "authorization", "action"),
            subscription_id=subscription,
            properties_message=_at(raw_record, "properties", "message"),
        )
        ip = ip_or_none(_at(raw_record, "httpRequest", "clientIpAddress"))
        observation_id = f"azure-activity:{subscription}:{event_data_id}"
        return (
            Observation(
                observation_id=observation_id,
                timestamp=timestamp,
                timestamp_precision=precision,
                raw_reference=SourceRef(
                    source_type=AZURE_ACTIVITY_SOURCE_TYPE, source_event_id=observation_id
                ),
                event=EventMetadata(kind="event", action=operation, dataset=AZURE_ACTIVITY_DATASET),
                user=UserRef(name=activity.caller) if activity.caller else None,
                network=NetworkInfo(source=NetworkEndpoint(ip=ip)) if ip else None,
                cloud=CloudRef(provider="azure", account_id=subscription),
                azure_activity=activity,
            ),
        )


# ---------------------------------------------------------------------------
# The diagnostic-setting export of the same log (Event Hub / storage account)
# ---------------------------------------------------------------------------

AZURE_ACTIVITY_EXPORT_SOURCE_TYPE = "azure_activity_export"
_EXPORT_ADAPTER = "AzureActivityExportSourceAdapter"
#: Activity Log categories (the Azure Monitor schema's eight, and the
#: ``Write`` / ``Delete`` / ``Action`` / ``Read`` the export writes for
#: administrative operations). A diagnostic record of another category belongs
#: to another log (sign-ins, resource logs) and is not read here.
ACTIVITY_EXPORT_CATEGORIES = frozenset(
    {
        "administrative",
        "security",
        "servicehealth",
        "resourcehealth",
        "alert",
        "autoscale",
        "recommendation",
        "policy",
        "write",
        "delete",
        "action",
        "read",
    }
)


def is_azure_activity_export_record(record: Mapping[str, Any]) -> bool:
    """Whether ``record`` is an Activity Log event as a diagnostic setting
    exports it: flat ``operationName`` / ``category`` strings, ``time``,
    ``resourceId`` — and not an Entra ID record (same envelope, other log)."""
    resource, category = record.get("resourceId"), record.get("category")
    return (
        isinstance(record.get("operationName"), str)
        and isinstance(record.get("time"), str)
        and isinstance(resource, str)
        and "/providers/microsoft.aadiam" not in resource.casefold()
        and isinstance(category, str)
        and category.casefold() in ACTIVITY_EXPORT_CATEGORIES
    )


def _properties_result(properties: Any) -> str | None:
    """``properties.result`` when it is a string. ``properties`` may be logged
    as an object or as JSON text of one (Elastic's pipeline parses the text)."""
    if isinstance(properties, str):
        try:
            properties = json.loads(properties)
        except ValueError:
            return None
    if not isinstance(properties, Mapping):
        return None
    result = properties.get("result")
    return result if isinstance(result, str) and result.strip() else None


class AzureActivityExportSourceAdapter:
    """Activity Log events in the diagnostic-export layout -> one ``Observation``
    each (ADR-0015 Amendment D).

    **Event time:** ``time``, ISO 8601 with a zone; without one it is refused.
    **Identity:** the layout carries no event id, so the Observation id is the
    SHA-256 of the record's canonical JSON — the same record always gets the
    same id, and two different records never share one.
    **Exact values:** ``operationName``, ``category``, ``resultType``, ``level``,
    ``resourceId``, ``correlationId`` and ``properties.result`` as logged. The
    REST form's ``status`` is a different vocabulary and is not filled from
    ``resultType``.
    """

    @property
    def source_type(self) -> str:
        return AZURE_ACTIVITY_EXPORT_SOURCE_TYPE

    def to_observations(self, raw_record: Any) -> tuple[Observation, ...]:
        if not isinstance(raw_record, Mapping) or not is_azure_activity_export_record(raw_record):
            raise SourceAdapterError(f"{_EXPORT_ADAPTER}: not an exported Activity Log event")
        timestamp, precision = zoned_iso_time(raw_record["time"], "time", _EXPORT_ADAPTER)
        operation = at_path(raw_record, ("operationName",), _EXPORT_ADAPTER)
        if operation is None:
            raise SourceAdapterError(f"{_EXPORT_ADAPTER}: operationName is blank")
        result_type = raw_record.get("resultType")
        activity = AzureActivityRef(
            correlation_id=at_path(raw_record, ("correlationId",), _EXPORT_ADAPTER),
            operation_name=operation,
            category=at_path(raw_record, ("category",), _EXPORT_ADAPTER),
            resource_id=at_path(raw_record, ("resourceId",), _EXPORT_ADAPTER),
            level=at_path(raw_record, ("level",), _EXPORT_ADAPTER),
            result_type=result_type if isinstance(result_type, str) and result_type else None,
            properties_result=_properties_result(raw_record.get("properties")),
        )
        caller_ip = raw_record.get("callerIpAddress")
        ip = ip_or_none(caller_ip) if isinstance(caller_ip, str) else None
        canonical = json.dumps(
            raw_record, sort_keys=True, separators=(",", ":"), ensure_ascii=False
        )
        digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
        observation_id = f"azure-activity-export:sha256:{digest}"
        return (
            Observation(
                observation_id=observation_id,
                timestamp=timestamp,
                timestamp_precision=precision,
                raw_reference=SourceRef(
                    source_type=AZURE_ACTIVITY_EXPORT_SOURCE_TYPE, source_event_id=observation_id
                ),
                event=EventMetadata(kind="event", action=operation, dataset=AZURE_ACTIVITY_DATASET),
                network=NetworkInfo(source=NetworkEndpoint(ip=ip)) if ip else None,
                cloud=CloudRef(provider="azure"),
                azure_activity=activity,
            ),
        )


__all__ = [
    "ACTIVITY_EXPORT_CATEGORIES",
    "AZURE_ACTIVITY_DATASET",
    "AZURE_ACTIVITY_EXPORT_SOURCE_TYPE",
    "AZURE_ACTIVITY_SOURCE_TYPE",
    "AzureActivityExportSourceAdapter",
    "AzureActivitySourceAdapter",
    "is_azure_activity_export_record",
    "is_azure_activity_record",
]
